    "type": "trigger",
    "name": "storage_profile_runtime_legacy_update_guard",
    "tableName": "storage_profile_runtime",
    "sql": "CREATE TRIGGER storage_profile_runtime_legacy_update_guard BEFORE UPDATE ON storage_profile_runtime WHEN (EXISTS(SELECT 1 FROM storage_profiles p WHERE p.id=NEW.storage_profile_id AND p.adapter_type IN('r2','switchdrive')))\nBEGIN SELECT RAISE(ABORT,'Profile write readiness requires explicit shadow admission') WHERE NOT(EXISTS(SELECT 1 FROM file_authority_control WHERE singleton=1 AND mode='overlap')) OR OLD.state<>'read_only' OR NEW.state<>'read_write' OR NEW.storage_profile_id IS NOT OLD.storage_profile_id OR NEW.registered_at IS NOT OLD.registered_at OR NEW.retired_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM file_shadow_profile_enablements e WHERE e.storage_profile_id=NEW.storage_profile_id AND NEW.activated_at IS e.enabled_at); END"
