export function localProfileV26ExpectedObjects(): readonly InstallationSchemaObject[] {
  const replacement = new Map(LOCAL_PROFILE_OBJECT_REPLACEMENTS.map(object => [object.name, object]));
  if (replacement.size !== 22 || LOCAL_PROFILE_NEW_OBJECTS.length !== 26) throw new Error("Unexpected RT3 source-authored object plan");
  const objects = [...PORTABLE_RUNTIME_SCHEMA_STATEMENTS.map(object => replacement.get(object.name) ?? object), ...LOCAL_PROFILE_NEW_OBJECTS];
  if (new Set(objects.map(object => object.name)).size !== objects.length) throw new Error("Duplicate RT3 expected schema object");
  return objects;
}
